 const DAY=864e5,td=new Date();td.setHours(0,0,0,0);const key=d=>d.getFullYear()+'-'+d.getMonth()+'-'+d.getDate(),days=[],mp={};
 for(let i=sr-1;i>=0;i--){const d=new Date(td.getTime()-i*DAY),o={d,l:0,s:0};days.push(o);mp[key(d)]=o}
 e.forEach(x=>{if(!x.t)return;const o=mp[key(new Date(x.t))];if(o)o[x.a==='l'?'l':'s']++});
 const mx=Math.max(1,...days.map(o=>o.l+o.s)),fd=d=>d.toLocaleDateString(loc,{day:'numeric',month:'short'});
 const chart=`<div class="ac">${days.map((o,i)=>{const lb=fd(o.d)+': '+t('detCat',{x:'',l:o.l,s:o.s}).replace(/^: ?/,'');return `<button class="col" style="--i:${i}" data-sc="${esc(lb)}" aria-label="${esc(lb)}"><i class="sk" style="height:${o.s/mx*100}%"></i><i class="lk" style="height:${o.l/mx*100}%"></i></button>`}).join('')}</div><div class="meta" style="display:flex;justify-content:space-between"><span>${fd(days[0].d)}</span><span>${fd(days[sr-1].d)}</span></div>`;
 const rng=[7,14,30].map(v=>`<button class="chip ${sr===v?'on':''}" data-sr="${v}">${v} ${t('daysU')}</button>`).join('');
