 const byDay={};e.forEach(x=>{if(x.t){const k=key(new Date(x.t));byDay[k]=(byDay[k]||0)+1}});const bk=Object.keys(byDay).sort((a,b)=>byDay[b]-byDay[a])[0];
 const ins=[],top=ks[0];
 if(L.length>=2&&cc[top].l>0)ins.push(t('inTop',{x:tx(CATS[top]),n:cc[top].l,m:L.length}));
