 const rt=k=>cc[k].s/(cc[k].l+cc[k].s),sk=ks.filter(k=>cc[k].l+cc[k].s>=2&&cc[k].s>=2).sort((a,b)=>rt(b)-rt(a)||cc[b].s-cc[a].s)[0];
 if(sk)ins.push(t('inSkip',{x:tx(CATS[sk]),n:cc[sk].s,m:cc[sk].l+cc[sk].s}));
